(* [comment removed for export] *)
Definition A_FLR_JT : Z := 0x3c698.
Lemma fliplr_jt : forall (m : mem), mem_inv asegs m -> ro_cells asegs m A_FLR_JT [CB 4 [Z_to_bv 8 120; Z_to_bv 8 146; Z_to_bv 8 16; Z_to_bv 8 0]].
Proof.
  intros m MI.
  lazymatch goal with |- ro_cells _ _ ?A [CB _ ?bs] => change (ro_cells asegs m A [CB (length bs) bs]) end; (apply (Image.ro_cells_image asegs); [exact MI | vm_compute; reflexivity | unfold A_FLR_JT; lia | cbn; unfold A_FLR_JT; lia]).
Qed.

Section FlipLRDefs.
Variable RT : rt_sig.

(* [comment removed for export] *)
Definition pixFlipLR2_cps : Prop := flip_inplace2_cps RT e_pixFlipLR 3.

(* [comment removed for export] *)
Definition pixFlipLR_case (AL : Z) : Prop :=
  forall (Σ : rts RT) PMc (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         F fc (m : mem) (lo : Z) (pix : Z) (v : pixv) (cv : cmapv) (ras : list Z),
  fdfs_only PMc -> mat_stable PMc -> tp = Z_to_bv 64 TP_A ->
  a0 = Z_to_bv 64 pix -> a1 = Z_to_bv 64 pix -> pix1c (rt_live RT Σ) m pix v cv ->
  uctx m sp s0 ras -> po_rows e_pixFlipLR ra ras ->
  lenv RT Σ m sp lo (LSTK 5) -> lres RT Σ 3 2 4 ->
  bv_unsigned sp mod 32 = AL ->
  cps asegs (ASTA RT Σ PMc (eq (entry_st ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc e_pixFlipLR m)))
    (fun c => exists (Σ' : rts RT),
       ASTA RT Σ' PMc (fun ms => exists m', ret_stF ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 pix) F m' ms
          /\ lpost_f RT Σ Σ' m m' sp lo /\ keeps RT Σ Σ' sp [(p_data v, p_data v + rsize v)] m m' /\ pix1c (rt_live RT Σ') m' pix v cv) c
       /\ rt_live RT Σ' = rt_live RT Σ /\ rt_frames RT Σ' = rt_frames RT Σ /\ rt_sp0 RT Σ' = rt_sp0 RT Σ /\ rt_credit RT Σ - 4 <= rt_credit RT Σ').

Lemma pixFlipLR_of_cases : pixFlipLR_case 0 -> pixFlipLR_case 16 -> pixFlipLR2_cps.
